    private void verifyRelation(Map<String,Object> actual,Instant asOf){require(actual.keySet().equals(Set.of("versionId","requirementId","evidenceId","versionNo","subtaskId","executionId","uploadId","filename","contentType","size","sha256","createdAt","currentExecution","latestInExecution","issueCount","review","anchor","sharing","verificationCount")),"relation_view_has_only_the_safe_contract_fields");String id=string(actual.get("versionId"));Map<String,Object> version=jdbc.queryForMap("SELECT v.*,u.filename,u.content_type,s.current_execution_id FROM evidence_version v JOIN upload_session u ON u.id=v.upload_session_id JOIN inspection_subtask s ON s.id=v.subtask_id WHERE v.id=?",id);
        for(var field:Map.of("requirementId","requirement_id","evidenceId","evidence_id","subtaskId","subtask_id","executionId","execution_id","uploadId","upload_session_id","filename","filename","contentType","content_type","sha256","sha256").entrySet())require(java.util.Objects.equals(version.get(field.getValue()),actual.get(field.getKey())),"relation_metadata_matches_fixed_version");require(number(version.get("version_no"))==number(actual.get("versionNo"))&&number(version.get("size"))==number(actual.get("size"))&&instant(version.get("created_at")).equals(Instant.parse(string(actual.get("createdAt")))),"relation_fixed_numbers_and_utc_timestamp_match_sql");
        boolean current=version.get("execution_id").equals(version.get("current_execution_id"));long latest=count("SELECT MAX(version_no) FROM evidence_version WHERE requirement_id=? AND execution_id=?",version.get("requirement_id"),version.get("execution_id"));require(Boolean.valueOf(current).equals(actual.get("currentExecution"))&&Boolean.valueOf(latest==number(version.get("version_no"))).equals(actual.get("latestInExecution")),"relation_current_and_latest_flags_use_correct_execution_scope");
        require(number(actual.get("issueCount"))==count("SELECT COUNT(*) FROM issue WHERE evidence_version_id=?",id)&&number(actual.get("verificationCount"))==count("SELECT COUNT(*) FROM verification_record WHERE version_id=?",id),"independent_issue_and_verification_counts_do_not_multiply");
        Map<String,Object> review=object(actual.get("review")),sqlReview=jdbc.queryForMap("SELECT * FROM review_record WHERE evidence_version_id=?",id);require(sqlReview.get("id").equals(review.get("reviewRecordId"))&&sqlReview.get("decision").equals(review.get("decision"))&&sqlReview.get("reviewer_id").equals(review.get("reviewerId"))&&instant(sqlReview.get("created_at")).equals(Instant.parse(string(review.get("reviewedAt")))),"relation_formal_review_is_the_exact_version_conclusion");
        Map<String,Object> anchor=object(actual.get("anchor")),submission=jdbc.queryForMap("SELECT * FROM chain_submission WHERE version_id=?",id),attempt=jdbc.queryForMap("SELECT * FROM chain_attempt WHERE submission_id=? AND tx_id=?",submission.get("id"),submission.get("confirmed_tx_id"));require(submission.get("id").equals(anchor.get("chainSubmissionId"))&&submission.get("status").equals(anchor.get("anchorStatus"))&&submission.get("confirmed_tx_id").equals(anchor.get("confirmedTxId"))&&number(attempt.get("block_number"))==number(anchor.get("blockNumber"))&&number(attempt.get("validation_code"))==number(anchor.get("validationCode")),"relation_anchor_uses_original_confirmed_attempt");
        Map<String,Object> sharing=object(actual.get("sharing"));Map<String,String> predicates=Map.of("grantCount","1=1","pendingGrantCount","status='PENDING'","activeGrantCount","status='APPROVED' AND valid_until>?","rejectedGrantCount","status='REJECTED'","revokedGrantCount","status='REVOKED'","expiredGrantCount","status='APPROVED' AND valid_until<=?");for(var entry:predicates.entrySet()){long expected=entry.getValue().contains("?")?count("SELECT COUNT(*) FROM access_grant WHERE version_id=? AND ("+entry.getValue()+")",id,java.time.LocalDateTime.ofInstant(asOf,java.time.ZoneOffset.UTC)):count("SELECT COUNT(*) FROM access_grant WHERE version_id=? AND ("+entry.getValue()+")",id);require(number(sharing.get(entry.getKey()))==expected,"relation_sharing_count_matches_status_and_shared_database_asof");}
    }
