    static final class CountingLedger implements EvidenceLedgerClient{private final EvidenceLedgerClient real;private final AtomicInteger calls;CountingLedger(EvidenceLedgerClient real,AtomicInteger calls){this.real=real;this.calls=calls;}@Override public PreparedRegistration prepareRegistration(String evidence,int version,String hash)throws EndorseException{calls.incrementAndGet();return real.prepareRegistration(evidence,version,hash);}@Override public CommitCheckpoint submitPrepared(PreparedRegistration prepared)throws SubmitException{calls.incrementAndGet();return real.submitPrepared(prepared);}@Override public CommitOutcome queryCommit(CommitCheckpoint checkpoint)throws CommitStatusException{calls.incrementAndGet();return real.queryCommit(checkpoint);}@Override public EvidenceQuery queryEvidence(String evidence,int version)throws GatewayException{calls.incrementAndGet();return real.queryEvidence(evidence,version);}@Override public void close(){/* Original registry owns clients. */}}
